import numpy as np, json
def solve(inp):
    i=np.array(inp); H,W=i.shape
    cnt=Counter(i.ravel()); X=cnt.most_common(1)[0][0]
    sr=[r for r in range(H) if not (i[r]==X).any()]
    sc=[c for c in range(W) if not (i[:,c]==X).any()]
    out=[]
    for a,b in zip(sr,sr[1:]):
        row=[]
        for x,y in zip(sc,sc[1:]):
            cs={int(v) for v in i[[a,b],x,y]}
            # corner cells: (a,x),(a,y),(b,x),(b,y)
            cs=set([int(i[a,x]),int(i[a,y]),int(i[b,x]),int(i[b,y])])
            s=set(cs)-{X}
            val=X
            if len(s)==1 and next(iter(s))!=X:
                val=next(iter(s))
            row.append(val)
        out.append(row)
    return out
